#include <stdio.h>
void change_copy(int value) { value = 99; }
void change_object(int *value) { if (value) *value = 99; }
int main(void) {
 int n = 10;
 change_copy(n);
 printf("%d\n", n);
 change_object(&n);
 printf("%d\n", n);
 return 0;
}

#include <stdio.h>
void reset(int *value) { if (value != NULL) *value = 0; }
int main(void) { int count = 9; reset(&count); printf("%d\n", count); return 0; }
